fn solve(r: i8, g: i8, b: i8) -> i8 {
    // Promote to i32 to avoid any risk of overflow when summing.
    let ri = r as i32;
    let gi = g as i32;
    let bi = b as i32;

    // Total items divided by 3 (floor).
    let cap_by_three = (ri + gi + bi) / 3;

    // We cannot form more tables than the sum of any two colors,
    // because each table must use at least two distinct colors.
    let cap_rg = ri + gi;
    let cap_rb = ri + bi;
    let cap_gb = gi + bi;

    // The answer is the minimum of those four bounds.
    let ans = cap_by_three.min(cap_rg).min(cap_rb).min(cap_gb);

    // The result is guaranteed to fit into i8 (max total sum is 3*127=381, 381/3=127).
    ans as i8
}

